#include <stdio.h>

// ============ 顺序表长什么样 ============
//
//   下标   0    1    2    3    4    5
//        ┌────┬────┬────┬────┬────┐
//   data │ 10 │ 20 │ 30 │    │    │
//        └────┴────┴────┴────┴────┘
//   length = 3
//
// 两个关键点：
//
//   1. 元素挨着放 —— 所以能"按下标随机访问"。想拿第 3 个，直接 data[2]，
//      一步到位，不需要从头数。这是链表做不到的（链表得走 3 步）。
//
//   2. length 记录**实际有几个元素**，它和 MAXSIZE（**最多能放几个**）
//      完全是两回事。表里只有 3 个元素，但数组开了 100 个格子 ——
//      后面那些格子里的内容是垃圾值，永远不要去看它们。

// 元素类型：想换成 char / double，只要改这一行
typedef int ElemType;

// 最多能放多少个元素
#define MAXSIZE 100

// 函数返回状态：OK 表示成功，ERROR 表示失败
// 用宏而不是 enum，是为了和教材写法保持一致
#define OK 1
#define ERROR 0

// 返回值类型
typedef int Status;

// 顺序表 = 定长数组 + 当前长度
// 注意 length 不是 MAXSIZE：它随插入删除变化，是这张表的"实际尺寸"
typedef struct
{
// 连续内存，元素一个挨一个
    ElemType data[MAXSIZE];
// 当前实际元素个数
    int length;
} SeqList;

// ============ 为什么不需要清空数组 ============
//
// 新手常写一个循环把 data[0..MAXSIZE-1] 全赋 0，其实完全没必要。
//
// 因为"表里有几个元素"是 **length 说了算**，而不是数组里有没有值。
// length = 0 就意味着"这是张空表"，后面格子里的垃圾值谁也看不见。
//
// 反过来，如果只清了数组却忘了 length = 0，那才是真的错。

// 参数是指针：要改调用者手里那张表本身，所以必须传地址
// 写成 SeqList *L 而不是 SeqList L，因为"初始化"要修改 L 的 length。
// 传值的话改的是副本，调用者那边毫无变化 —— 这是个高频错误。
Status InitList_Sq(SeqList *L)
{
// 空表：一个元素都没有 —— 这一句就够了
    L->length = 0;
// 约定：返回 OK 表示初始化成功
    return OK;
}

// ============ 插入要"搬家" ============
// 在位置 i 插入 e，意味着 e 要占住下标 i-1 那个格子。
// 但那个格子原本有元素，所以它以及它后面所有的元素都得往后挪一格：
//
//   插入前： 10  20  30  _   _        （length = 3，在下标 1 处插入 15）
//             0   1   2   3   4
//
//   后移：   10  20  __  30  _        ← 30 从下标 2 挪到 3
//                └── 20 从下标 1 挪到 2
//
//   填入：   10  15  20  30  _        ← e 放进腾出来的下标 1
//   length = 4
//
// ============ 为什么必须从后往前搬 ============
//
//   正确（j 从 length 递减到 i）：先搬最右边的，空位一路向左让出来
//       data[3] = data[2]   →  data[2] = data[1]   →  data[1] = e
//
//   错误（j 从 i 递增到 length）：先搬左边的，会把右边的值覆盖掉
//       data[1] = data[0]   →  data[2] = data[1]   ← 这里 data[1] 已经是 10 了！
//
// 一句话记住：**搬家永远从"没人占的那一头"开始搬**。

// L 是要改的表，i 是插入位置（1 基，不是下标），e 是待插入元素
Status ListInsert_Sq(SeqList *L, int i, ElemType e)
{
// 循环变量
    int j;

// 位置合法性：1 到 length+1 都算合法
// 为什么是 length+1？因为"插在最后一个元素后面"是允许的。
// 长度为 3 时，合法位置是 1、2、3、4；i=5 就越界了。
// 注意这里用的是 length 而不是 MAXSIZE —— 前者是"有几个元素"，
// 后者是"能装几个"，判断位置用前者。
    if (i < 1 || i > L->length + 1)
    {
        return ERROR;
    }

// 表满了也插不进去
// 这是顺序表天生的局限：容量是固定的，满了只能报错（或者扩容搬迁）。
// 链表没有这个问题 —— 内存够就能一直加。
    if (L->length >= MAXSIZE)
    {
        return ERROR;
    }

// 从最后一个元素开始，一个个往后挪一格
// j 从 length 递减到 i：注意 data[length] 这个格子本身是"空"的
// （不在 length 计数范围内），所以第一次赋值刚好把最后那个元素挪进空位。
// 循环结束时，下标 i-1 那个格子已经被腾出来了。
    for (j = L->length; j >= i; j--)
    {
        L->data[j] = L->data[j - 1];
    }

// 把 e 填进腾出来的空位
// 存的是下标，所以位置 i 对应 data[i-1]。这个 ±1 的转换是初学时
// 最容易写错的地方，建议在纸上画一遍。
    L->data[i - 1] = e;

// 元素多了一个
    L->length++;

// 插入成功
    return OK;
}

// ============ 删除也要"搬家"，方向相反 ============
//
//   删除前： 10  15  20  30  _        （length = 4，删除下标 1 的 15）
//             0   1   2   3   4
//
//   前移：   10  20  30  __  _        ← 20 从下标 2 挪到 1，30 从 3 挪到 2
//   length = 3
//
// 和插入正好相反：**删除要从前往后搬**。
// 因为这次空位在左边，得让右边的元素一个个往左填。
// 如果从后往前搬，就会把还没搬的元素覆盖掉。

// e 是"带回被删元素"的出口参数 —— 调用者想知道删掉的是谁
Status ListDelete_Sq(SeqList *L, int i, ElemType *e)
{
// 循环变量
    int j;

// 位置合法性：1 到 length
// 注意和插入的区别：这里上限是 length 而不是 length+1。
// 因为删除的是"已经存在的元素"，而长度为 3 的表里只存在 1、2、3 三个位置。
    if (i < 1 || i > L->length)
    {
        return ERROR;
    }

// 先把被删元素取出来 —— 必须在搬家之前做
// 因为它马上就要被后面的元素覆盖掉了，晚一步就取不到了。
    *e = L->data[i - 1];

// 从被删位置开始，后面的元素统统往前挪一格
// j 从 i 递增到 length-1：把 data[j] 搬到 data[j-1]。
// 循环结束后，最后一个位置 data[length-1] 的内容虽然还在，
// 但已经不在 length 计数范围内，等于被抛弃了。
    for (j = i; j < L->length; j++)
    {
        L->data[j - 1] = L->data[j];
    }

// 元素少了一个
    L->length--;

// 删除成功
    return OK;
}

// ============ 顺序查找 ============
//
//   找 30： 10  20  30  40
//           ↑   ↑   ↑
//           比  比  中 ✓        比较 3 次
//
// 这叫"顺序查找"，平均要比较 (n+1)/2 次，时间复杂度 O(n)。
//
// 如果这张表是**有序的**，可以改用二分查找，降到 O(log n)。
// 但二分要求"能按下标跳跃访问"—— 这恰好是顺序表的强项，
// 链表就做不了（链表中途没法直接跳到中间）。

// 返回"位序"（1 基），不是下标；找不到返回 0
// 为什么返回位序而不是下标？因为调用者拿到 0 就知道"没找到"，
// 而下标 0 是合法位置，用它当"没找到"会分不清。
int LocateElem_Sq(SeqList L, ElemType e)
{
// 循环变量
    int i;

// 从下标 0 扫到 length-1 —— 只扫"有效元素"那一段
// 一定用 length 做上界，不要用 MAXSIZE：
// 后面那些格子是垃圾值，扫进去可能"莫名奇妙找到"一个相等的东西。
    for (i = 0; i < L.length; i++)
    {
// 相等就返回它的位序（下标 +1）
        if (L.data[i] == e)
        {
            return i + 1;
        }
    }

// 扫完了还没有，就是没有
    return 0;
}

// ============ 为什么要"一步一打印" ============
//
// 顺序表的 bug 大多不是崩溃，而是**悄悄出错**：
// 元素顺序错了、length 忘了加、搬家方向反了 —— 程序照跑不误，
// 只是数据不对。所以每一步都打印出来，肉眼一比对就露馅了。

// 打印辅助函数放在 main 之前
// 它不属于要默写的核心操作，所以直接给出、不用自己写
static void PrintList(const char *tag, SeqList L)
{
    int i;

    printf("%s length=%d : ", tag, L.length);
    for (i = 0; i < L.length; i++)
    {
        printf("%d ", L.data[i]);
    }
    printf("\n");
}

// 主函数
int main(void)
{
// 定义一张表
    SeqList L;
// 用来接住被删除的元素
    ElemType e;
// 查找结果（位序）
    int pos;

// 先初始化 —— 别忘了，否则 length 是随机值
    InitList_Sq(&L);

// 依次在表尾追加 10、20、40
// 插到 length+1 的位置就是"追加到末尾"，每次只搬家 0 次，是最省的情形。
    ListInsert_Sq(&L, 1, 10);
    ListInsert_Sq(&L, 2, 20);
    ListInsert_Sq(&L, 3, 40);
    PrintList("追加 10 20 40 后:", L);

// 在下标 2（位序 3）处插入 30，让表变成有序的
// 这一次要搬家 1 个元素（40 后移），刚好演示"插入要挪位置"。
    ListInsert_Sq(&L, 3, 30);
    PrintList("在下标 2 处插入 30:", L);

// 查找 30 在哪
    pos = LocateElem_Sq(L, 30);
    printf("查找 30 -> 位序 %d（下标 %d）\n", pos, pos - 1);

// 查找一个不存在的值
    pos = LocateElem_Sq(L, 99);
    printf("查找 99 -> 位序 %d（0 表示没找到）\n", pos);

// 删除位序 2 的元素，看它是不是 20
// 这次要搬家 2 个元素（30、40 前移），演示"删除要往前填"。
    ListDelete_Sq(&L, 2, &e);
    printf("删除位序 2 -> 拿到的元素是 %d\n", e);
    PrintList("删除后:", L);

// 越界插入应该被挡住
    if (ListInsert_Sq(&L, 99, 7) == ERROR)
    {
        printf("在位序 99 插入 -> 被拒绝（越界）\n");
    }
    PrintList("越界插入后:", L);

// 正常结束
    return 0;
}

