#include <stdio.h>


// 元素类型：想换成 char / double，只要改这一行
typedef int ElemType;

// 最多能放多少个元素
#define MAXSIZE 100

// 函数返回状态：OK 表示成功，ERROR 表示失败
#define OK 1
#define ERROR 0

// 返回值类型
typedef int Status;

// 顺序表 = 定长数组 + 当前长度
typedef struct
{
// 连续内存，元素一个挨一个
    ElemType data[MAXSIZE];
// 当前实际元素个数
    int length;
} SeqList;


// 参数是指针：要改调用者手里那张表本身，所以必须传地址
Status InitList_Sq(SeqList *L)
{
// 空表：一个元素都没有 —— 这一句就够了
    L->length = 0;
// 约定：返回 OK 表示初始化成功
    return OK;
}


// L 是要改的表，i 是插入位置（1 基，不是下标），e 是待插入元素
Status ListInsert_Sq(SeqList *L, int i, ElemType e)
{
// 循环变量
    int j;

// 位置合法性：1 到 length+1 都算合法
    if (i < 1 || i > L->length + 1)
    {
        return ERROR;
    }

// 表满了也插不进去
    if (L->length >= MAXSIZE)
    {
        return ERROR;
    }

// 从最后一个元素开始，一个个往后挪一格
    for (j = L->length; j >= i; j--)
    {
        L->data[j] = L->data[j - 1];
    }

// 把 e 填进腾出来的空位
    L->data[i - 1] = e;

// 元素多了一个
    L->length++;

// 插入成功
    return OK;
}


// e 是"带回被删元素"的出口参数 —— 调用者想知道删掉的是谁
Status ListDelete_Sq(SeqList *L, int i, ElemType *e)
{
// 循环变量
    int j;

// 位置合法性：1 到 length
    if (i < 1 || i > L->length)
    {
        return ERROR;
    }

// 先把被删元素取出来 —— 必须在搬家之前做
    *e = L->data[i - 1];

// 从被删位置开始，后面的元素统统往前挪一格
    for (j = i; j < L->length; j++)
    {
        L->data[j - 1] = L->data[j];
    }

// 元素少了一个
    L->length--;

// 删除成功
    return OK;
}


// 返回"位序"（1 基），不是下标；找不到返回 0
int LocateElem_Sq(SeqList L, ElemType e)
{
// 循环变量
    int i;

// 从下标 0 扫到 length-1 —— 只扫"有效元素"那一段
    for (i = 0; i < L.length; i++)
    {
// 相等就返回它的位序（下标 +1）
        if (L.data[i] == e)
        {
            return i + 1;
        }
    }

// 扫完了还没有，就是没有
    return 0;
}


// 打印辅助函数放在 main 之前
static void PrintList(const char *tag, SeqList L)
{
    int i;

    printf("%s length=%d : ", tag, L.length);
    for (i = 0; i < L.length; i++)
    {
        printf("%d ", L.data[i]);
    }
    printf("\n");
}

// 主函数
int main(void)
{
// 定义一张表
    SeqList L;
// 用来接住被删除的元素
    ElemType e;
// 查找结果（位序）
    int pos;

// 先初始化 —— 别忘了，否则 length 是随机值
    InitList_Sq(&L);

// 依次在表尾追加 10、20、40
    ListInsert_Sq(&L, 1, 10);
    ListInsert_Sq(&L, 2, 20);
    ListInsert_Sq(&L, 3, 40);
    PrintList("追加 10 20 40 后:", L);

// 在下标 2（位序 3）处插入 30，让表变成有序的
    ListInsert_Sq(&L, 3, 30);
    PrintList("在下标 2 处插入 30:", L);

// 查找 30 在哪
    pos = LocateElem_Sq(L, 30);
    printf("查找 30 -> 位序 %d（下标 %d）\n", pos, pos - 1);

// 查找一个不存在的值
    pos = LocateElem_Sq(L, 99);
    printf("查找 99 -> 位序 %d（0 表示没找到）\n", pos);

// 删除位序 2 的元素，看它是不是 20
    ListDelete_Sq(&L, 2, &e);
    printf("删除位序 2 -> 拿到的元素是 %d\n", e);
    PrintList("删除后:", L);

// 越界插入应该被挡住
    if (ListInsert_Sq(&L, 99, 7) == ERROR)
    {
        printf("在位序 99 插入 -> 被拒绝（越界）\n");
    }
    PrintList("越界插入后:", L);

// 正常结束
    return 0;
}

modes.none:
#include <stdio.h>


typedef int ElemType;

#define MAXSIZE 100

#define OK 1
#define ERROR 0

typedef int Status;

typedef struct
{
    ElemType data[MAXSIZE];
    int length;
} SeqList;


Status InitList_Sq(SeqList *L)
{
    L->length = 0;
    return OK;
}


Status ListInsert_Sq(SeqList *L, int i, ElemType e)
{
    int j;

    if (i < 1 || i > L->length + 1)
    {
        return ERROR;
    }

    if (L->length >= MAXSIZE)
    {
        return ERROR;
    }

    for (j = L->length; j >= i; j--)
    {
        L->data[j] = L->data[j - 1];
    }

    L->data[i - 1] = e;

    L->length++;

    return OK;
}


Status ListDelete_Sq(SeqList *L, int i, ElemType *e)
{
    int j;

    if (i < 1 || i > L->length)
    {
        return ERROR;
    }

    *e = L->data[i - 1];

    for (j = i; j < L->length; j++)
    {
        L->data[j - 1] = L->data[j];
    }

    L->length--;

    return OK;
}


int LocateElem_Sq(SeqList L, ElemType e)
{
    int i;

    for (i = 0; i < L.length; i++)
    {
        if (L.data[i] == e)
        {
            return i + 1;
        }
    }

    return 0;
}


static void PrintList(const char *tag, SeqList L)
{
    int i;

    printf("%s length=%d : ", tag, L.length);
    for (i = 0; i < L.length; i++)
    {
        printf("%d ", L.data[i]);
    }
    printf("\n");
}

int main(void)
{
    SeqList L;
    ElemType e;
    int pos;

    InitList_Sq(&L);

    ListInsert_Sq(&L, 1, 10);
    ListInsert_Sq(&L, 2, 20);
    ListInsert_Sq(&L, 3, 40);
    PrintList("追加 10 20 40 后:", L);

    ListInsert_Sq(&L, 3, 30);
    PrintList("在下标 2 处插入 30:", L);

    pos = LocateElem_Sq(L, 30);
    printf("查找 30 -> 位序 %d（下标 %d）\n", pos, pos - 1);

    pos = LocateElem_Sq(L, 99);
    printf("查找 99 -> 位序 %d（0 表示没找到）\n", pos);

    ListDelete_Sq(&L, 2, &e);
    printf("删除位序 2 -> 拿到的元素是 %d\n", e);
    PrintList("删除后:", L);

    if (ListInsert_Sq(&L, 99, 7) == ERROR)
    {
        printf("在位序 99 插入 -> 被拒绝（越界）\n");
    }
    PrintList("越界插入后:", L);

    return 0;
}
